('CAT-FIN-03', 'FIN', 'financial_aid', 'Satisfactory progress appeal', 'normal', 1, 0, 'Appeals after losing aid eligibility for academic progress; requires human decision.'),
('CAT-FIN-04', 'FIN', 'financial_aid', 'Tuition payment and refunds', 'normal', 0, 1, 'Payment plans, due dates, late fees and tuition refunds.'),
('CAT-REG-01', 'REG', 'registration', 'Add, drop and withdraw', 'normal', 0, 1, 'Course add/drop windows, withdrawal deadlines and fees.'),
('CAT-REG-02', 'REG', 'registration', 'Holds and prerequisites', 'normal', 0, 0, 'Registration holds, prerequisite overrides and credit-load limits.'),
