('CAT-IT-03', 'IT', 'it', 'Wi-Fi and software licenses', 'low', 0, 0, 'Campus Wi-Fi registration, VPN and licensed software.'),
('CAT-IT-04', 'IT', 'it', 'Security incident', 'high', 1, 0, 'Compromised accounts and phishing; requires human security review.'),
