INSERT INTO "knowledge_article" ("article_id", "policy_id", "version_no", "title", "body", "effective_from", "effective_to", "status", "supersedes_article_id", "author_id", "published_at") VALUES
('KB-000001', 'POL-FIN-2026-001', 1, 'Aid status and disbursement: Standard Procedure', 'Aid status and disbursement: Standard Procedure (version 1). Effective 2025-08-14. Financial aid is disbursed 10 days after the term census date. Aid requires enrollment in at least 9 credit hours. Exceptions require written approval from the owning office.', '2025-08-14', '2026-05-12', 'superseded', NULL, 'REQ-000106', '2025-08-07T09:31:00'),
('KB-000002', 'POL-FIN-2026-001', 2, 'Aid status and disbursement: Standard Procedure', 'Aid status and disbursement: Standard Procedure (version 2). Effective 2026-05-13. Financial aid is disbursed 10 days after the term census date. Aid requires enrollment in at least 12 credit hours. Exceptions require written approval from the owning office.', '2026-05-13', NULL, 'current', 'KB-000001', 'REQ-000106', '2026-04-20T10:43:00'),
('KB-000003', 'POL-FIN-2026-002', 1, 'Verification documents: Standard Procedure', 'Verification documents: Standard Procedure (version 1). Effective 2024-12-02. Verification documents are due within 21 days of the request notice. Submitted documents are reviewed within 10 business days. Exceptions require written approval from the owning office.', '2024-12-02', '2025-07-04', 'superseded', NULL, 'REQ-000105', '2024-11-06T11:36:00'),
('KB-000004', 'POL-FIN-2026-002', 2, 'Verification documents: Standard Procedure', 'Verification documents: Standard Procedure (version 2). Effective 2025-07-05. Verification documents are due within 21 days of the request notice. Submitted documents are reviewed within 15 business days. Exceptions require written approval from the owning office.', '2025-07-05', '2026-08-12', 'superseded', 'KB-000003', 'REQ-000105', '2025-06-18T10:46:00'),
('KB-000005', 'POL-FIN-2026-002', 3, 'Verification documents: Standard Procedure', 'Verification documents: Standard Procedure (version 3). Effective 2026-08-13. Verification documents are due within 45 days of the request notice. Submitted documents are reviewed within 5 business days. Exceptions require written approval from the owning office.', '2026-08-13', NULL, 'current', 'KB-000004', 'REQ-000105', '2026-07-17T10:37:00'),
('KB-000006', 'POL-FIN-2026-003', 1, 'Satisfactory progress appeal: Standard Procedure', 'Satisfactory progress appeal: Standard Procedure (version 1). Effective 2025-03-16. Minimum cumulative GPA for aid eligibility is 2.0. Progress appeals must be filed within 14 days of the notice. Exceptions require written approval from the owning office.', '2025-03-16', '2026-02-01', 'superseded', NULL, 'REQ-000105', '2025-03-01T13:17:00'),
('KB-000007', 'POL-FIN-2026-003', 2, 'Satisfactory progress appeal: Standard Procedure', 'Satisfactory progress appeal: Standard Procedure (version 2). Effective 2026-02-02. Minimum cumulative GPA for aid eligibility is 2.25. Progress appeals must be filed within 14 days of the notice. Exceptions require written approval from the owning office.', '2026-02-02', NULL, 'current', 'KB-000006', 'REQ-000107', '2026-01-27T13:13:00'),
('KB-000008', 'POL-FIN-2026-004', 1, 'Tuition payment and refunds: Standard Procedure', 'Tuition payment and refunds: Standard Procedure (version 1). Effective 2024-12-02. Tuition is due 10 days before the term start date. A late fee of 5.0 percent applies to overdue balances. Exceptions require written approval from the owning office.', '2024-12-02', '2025-05-19', 'superseded', NULL, 'REQ-000105', '2024-11-05T12:15:00'),
('KB-000009', 'POL-FIN-2026-004', 2, 'Tuition payment and refunds: Standard Procedure', 'Tuition payment and refunds: Standard Procedure (version 2). Effective 2025-05-20. Tuition is due 7 days before the term start date. A late fee of 5.0 percent applies to overdue balances. Exceptions require written approval from the owning office.', '2025-05-20', NULL, 'current', 'KB-000008', 'REQ-000105', '2025-05-07T13:25:00'),
('KB-000010', 'POL-REG-2026-001', 1, 'Add, drop and withdraw: Standard Procedure', 'Add, drop and withdraw: Standard Procedure (version 1). Effective 2023-10-12. Courses may be added through day 5 of the term. Withdrawal with a W grade is allowed through day 50 of the term. Exceptions require written approval from the owning office.', '2023-10-12', '2024-08-22', 'superseded', NULL, 'REQ-000109', '2023-10-07T13:37:00'),
('KB-000011', 'POL-REG-2026-001', 2, 'Add, drop and withdraw: Standard Procedure', 'Add, drop and withdraw: Standard Procedure (version 2). Effective 2024-08-23. Courses may be added through day 5 of the term. Withdrawal with a W grade is allowed through day 45 of the term. Exceptions require written approval from the owning office.', '2024-08-23', '2025-08-26', 'superseded', 'KB-000010', 'REQ-000110', '2024-08-02T12:09:00'),
('KB-000012', 'POL-REG-2026-001', 3, 'Add, drop and withdraw: Standard Procedure', 'Add, drop and withdraw: Standard Procedure (version 3). Effective 2025-08-27. Courses may be added through day 5 of the term. Withdrawal with a W grade is allowed through day 60 of the term. Exceptions require written approval from the owning office.', '2025-08-27', NULL, 'current', 'KB-000011', 'REQ-000109', '2025-08-21T10:28:00'),
('KB-000013', 'POL-REG-2026-002', 1, 'Holds and prerequisites: Standard Procedure', 'Holds and prerequisites: Standard Procedure (version 1). Effective 2025-07-14. Registration holds are cleared within 2 business days of resolution. Prerequisite overrides must be approved by the course instructor. Exceptions require written approval from the owning office.', '2025-07-14', '2026-07-10', 'superseded', NULL, 'REQ-000109', '2025-06-16T12:24:00'),
('KB-000014', 'POL-REG-2026-002', 2, 'Holds and prerequisites: Standard Procedure', 'Holds and prerequisites: Standard Procedure (version 2). Effective 2026-07-11. Registration holds are cleared within 1 business days of resolution. Prerequisite overrides must be approved by the academic advisor. Exceptions require written approval from the owning office.', '2026-07-11', NULL, 'current', 'KB-000013', 'REQ-000109', '2026-07-01T11:30:00'),
('KB-000015', 'POL-REG-2026-003', 1, 'Transcripts and records: Standard Procedure', 'Transcripts and records: Standard Procedure (version 1). Effective 2025-10-02. Official transcripts are processed within 3 business days. Each official transcript costs 5 USD. Exceptions require written approval from the owning office.', '2025-10-02', '2026-06-12', 'superseded', NULL, 'REQ-000110', '2025-09-08T09:09:00'),
('KB-000016', 'POL-REG-2026-003', 2, 'Transcripts and records: Standard Procedure', 'Transcripts and records: Standard Procedure (version 2). Effective 2026-06-13. Official transcripts are processed within 2 business days. Each official transcript costs 10 USD. Exceptions require written approval from the owning office.', '2026-06-13', NULL, 'current', 'KB-000015', 'REQ-000110', '2026-05-20T09:19:00'),
('KB-000017', 'POL-REG-2026-004', 1, 'Grade change and roster correction: Standard Procedure', 'Grade change and roster correction: Standard Procedure (version 1). Effective 2023-11-13. Grade changes must be filed within 45 days after the term ends. Grade changes require approval from the dean of the college. Exceptions require written approval from the owning office.', '2023-11-13', '2024-04-05', 'superseded', NULL, 'REQ-000108', '2023-10-15T11:31:00'),
('KB-000018', 'POL-REG-2026-004', 2, 'Grade change and roster correction: Standard Procedure', 'Grade change and roster correction: Standard Procedure (version 2). Effective 2024-04-06. Grade changes must be filed within 60 days after the term ends. Grade changes require approval from the dean of the college. Exceptions require written approval from the owning office.', '2024-04-06', '2025-04-28', 'superseded', 'KB-000017', 'REQ-000109', '2024-03-31T13:34:00'),
('KB-000019', 'POL-REG-2026-004', 3, 'Grade change and roster correction: Standard Procedure', 'Grade change and roster correction: Standard Procedure (version 3). Effective 2025-04-29. Grade changes must be filed within 60 days after the term ends. Grade changes require approval from the registrar. Exceptions require written approval from the owning office.', '2025-04-29', '2025-12-17', 'superseded', 'KB-000018', 'REQ-000109', '2025-04-17T10:21:00'),
('KB-000020', 'POL-REG-2026-004', 4, 'Grade change and roster correction: Standard Procedure', 'Grade change and roster correction: Standard Procedure (version 4). Effective 2025-12-18. Grade changes must be filed within 90 days after the term ends. Grade changes require approval from the registrar. Exceptions require written approval from the owning office.', '2025-12-18', NULL, 'current', 'KB-000019', 'REQ-000110', '2025-11-18T13:11:00'),
('KB-000021', 'POL-IT-2026-001', 1, 'Account, password and MFA: Standard Procedure', 'Account, password and MFA: Standard Procedure (version 1). Effective 2025-05-24. Passwords expire every 180 days. Accounts lock for 30 minutes after five failed sign-ins. Exceptions require written approval from the owning office.', '2025-05-24', '2026-08-07', 'superseded', NULL, 'REQ-000113', '2025-05-06T12:54:00'),
('KB-000022', 'POL-IT-2026-001', 2, 'Account, password and MFA: Standard Procedure', 'Account, password and MFA: Standard Procedure (version 2). Effective 2026-08-08. Passwords expire every 365 days. Accounts lock for 30 minutes after five failed sign-ins. Exceptions require written approval from the owning office.', '2026-08-08', NULL, 'current', 'KB-000021', 'REQ-000111', '2026-07-31T10:32:00'),
('KB-000023', 'POL-IT-2026-002', 1, 'LMS and course access: Standard Procedure', 'LMS and course access: Standard Procedure (version 1). Effective 2024-04-24. Courses appear in the learning platform within 4 hours of enrollment. Instructor course shells open 14 days before the term starts. Exceptions require written approval from the owning office.', '2024-04-24', '2025-04-16', 'superseded', NULL, 'REQ-000111', '2024-03-30T12:32:00'),
('KB-000024', 'POL-IT-2026-002', 2, 'LMS and course access: Standard Procedure', 'LMS and course access: Standard Procedure (version 2). Effective 2025-04-17. Courses appear in the learning platform within 4 hours of enrollment. Instructor course shells open 7 days before the term starts. Exceptions require written approval from the owning office.', '2025-04-17', NULL, 'current', 'KB-000023', 'REQ-000112', '2025-04-09T12:19:00'),
('KB-000025', 'POL-IT-2026-003', 1, 'Wi-Fi and software licenses: Standard Procedure', 'Wi-Fi and software licenses: Standard Procedure (version 1). Effective 2025-06-26. Each user may register up to 5 devices. Licensed software is activated for 180 days per grant. Exceptions require written approval from the owning office.', '2025-06-26', '2026-05-19', 'superseded', NULL, 'REQ-000113', '2025-06-13T12:55:00'),
('KB-000026', 'POL-IT-2026-003', 2, 'Wi-Fi and software licenses: Standard Procedure', 'Wi-Fi and software licenses: Standard Procedure (version 2). Effective 2026-05-20. Each user may register up to 3 devices. Licensed software is activated for 180 days per grant. Exceptions require written approval from the owning office.', '2026-05-20', NULL, 'current', 'KB-000025', 'REQ-000111', '2026-05-02T12:58:00'),
('KB-000027', 'POL-IT-2026-004', 1, 'Security incident: Standard Procedure', 'Security incident: Standard Procedure (version 1). Effective 2025-09-20. Suspected compromises must be reported within 48 hours. Compromised accounts are frozen for up to 48 hours during review. Exceptions require written approval from the owning office.', '2025-09-20', '2026-04-05', 'superseded', NULL, 'REQ-000113', '2025-08-25T14:00:00'),
('KB-000028', 'POL-IT-2026-004', 2, 'Security incident: Standard Procedure', 'Security incident: Standard Procedure (version 2). Effective 2026-04-06. Suspected compromises must be reported within 4 hours. Compromised accounts are frozen for up to 72 hours during review. Exceptions require written approval from the owning office.', '2026-04-06', NULL, 'current', 'KB-000027', 'REQ-000113', '2026-03-30T11:25:00'),
('KB-000029', 'POL-ACC-2026-001', 1, 'Accommodation intake information: Standard Procedure', 'Accommodation intake information: Standard Procedure (version 1). Effective 2024-04-11. Intake requests are acknowledged within 2 business days. Supporting documentation must be dated within 3 years. Exceptions require written approval from the owning office.', '2024-04-11', '2025-03-27', 'superseded', NULL, 'REQ-000114', '2024-03-23T09:57:00'),
('KB-000030', 'POL-ACC-2026-001', 2, 'Accommodation intake information: Standard Procedure', 'Accommodation intake information: Standard Procedure (version 2). Effective 2025-03-28. Intake requests are acknowledged within 5 business days. Supporting documentation must be dated within 3 years. Exceptions require written approval from the owning office.', '2025-03-28', '2025-11-23', 'superseded', 'KB-000029', 'REQ-000114', '2025-03-19T13:15:00'),
('KB-000031', 'POL-ACC-2026-001', 3, 'Accommodation intake information: Standard Procedure', 'Accommodation intake information: Standard Procedure (version 3). Effective 2025-11-24. Intake requests are acknowledged within 3 business days. Supporting documentation must be dated within 3 years. Exceptions require written approval from the owning office.', '2025-11-24', '2026-05-09', 'retired', 'KB-000030', 'REQ-000114', '2025-10-31T13:41:00'),
('KB-000032', 'POL-ACC-2026-002', 1, 'Accommodation determination: Standard Procedure', 'Accommodation determination: Standard Procedure (version 1). Effective 2024-12-06. Accommodation determinations are issued within 15 business days. Determination appeals must be filed within 30 days. Exceptions require written approval from the owning office.', '2024-12-06', '2025-07-19', 'superseded', NULL, 'REQ-000116', '2024-11-17T13:35:00'),
('KB-000033', 'POL-ACC-2026-002', 2, 'Accommodation determination: Standard Procedure', 'Accommodation determination: Standard Procedure (version 2). Effective 2025-07-20. Accommodation determinations are issued within 10 business days. Determination appeals must be filed within 30 days. Exceptions require written approval from the owning office.', '2025-07-20', NULL, 'current', 'KB-000032', 'REQ-000116', '2025-06-30T09:37:00'),
('KB-000034', 'POL-ACC-2026-003', 1, 'Assistive technology: Standard Procedure', 'Assistive technology: Standard Procedure (version 1). Effective 2023-09-01. Assistive technology may be loaned for 90 days per term. Assistive technology requests need 10 days of lead time. Exceptions require written approval from the owning office.', '2023-09-01', '2024-08-02', 'superseded', NULL, 'REQ-000115', '2023-08-21T12:38:00'),
('KB-000035', 'POL-ACC-2026-003', 2, 'Assistive technology: Standard Procedure', 'Assistive technology: Standard Procedure (version 2). Effective 2024-08-03. Assistive technology may be loaned for 30 days per term. Assistive technology requests need 10 days of lead time. Exceptions require written approval from the owning office.', '2024-08-03', '2025-04-14', 'superseded', 'KB-000034', 'REQ-000116', '2024-07-13T10:21:00'),
('KB-000036', 'POL-ACC-2026-003', 3, 'Assistive technology: Standard Procedure', 'Assistive technology: Standard Procedure (version 3). Effective 2025-04-15. Assistive technology may be loaned for 60 days per term. Assistive technology requests need 10 days of lead time. Exceptions require written approval from the owning office.', '2025-04-15', '2026-05-29', 'superseded', 'KB-000035', 'REQ-000115', '2025-04-07T13:51:00'),
('KB-000037', 'POL-ACC-2026-003', 4, 'Assistive technology: Standard Procedure', 'Assistive technology: Standard Procedure (version 4). Effective 2026-05-30. Assistive technology may be loaned for 90 days per term. Assistive technology requests need 5 days of lead time. Exceptions require written approval from the owning office.', '2026-05-30', NULL, 'current', 'KB-000036', 'REQ-000115', '2026-05-10T12:48:00'),
('KB-000038', 'POL-ACC-2026-004', 1, 'Exam accommodation logistics: Standard Procedure', 'Exam accommodation logistics: Standard Procedure (version 1). Effective 2024-05-21. Accommodated exams must be booked 3 days before the exam date. Standard extended time is 50 percent of the regular exam length. Exceptions require written approval from the owning office.', '2024-05-21', '2025-06-07', 'superseded', NULL, 'REQ-000116', '2024-05-13T13:02:00'),
('KB-000039', 'POL-ACC-2026-004', 2, 'Exam accommodation logistics: Standard Procedure', 'Exam accommodation logistics: Standard Procedure (version 2). Effective 2025-06-08. Accommodated exams must be booked 5 days before the exam date. Standard extended time is 50 percent of the regular exam length. Exceptions require written approval from the owning office.', '2025-06-08', '2026-05-28', 'superseded', 'KB-000038', 'REQ-000115', '2025-05-19T11:12:00'),
('KB-000040', 'POL-ACC-2026-004', 3, 'Exam accommodation logistics: Standard Procedure', 'Exam accommodation logistics: Standard Procedure (version 3). Effective 2026-05-29. Accommodated exams must be booked 3 days before the exam date. Standard extended time is 50 percent of the regular exam length. Exceptions require written approval from the owning office.', '2026-05-29', NULL, 'current', 'KB-000039', 'REQ-000115', '2026-05-22T12:10:00');
