INSERT INTO "message" ("message_id", "ticket_id", "message_seq", "sender_type", "sender_id", "message_type", "sent_at", "body") VALUES
('MSG-TKT-2026-000001-001', 'TKT-2026-000001', 1, 'requester', 'REQ-000011', 'question', '2026-01-05T11:25:00', 'Hello, quick question: When will my financial aid be disbursed to my account?'),
('MSG-TKT-2026-000001-002', 'TKT-2026-000001', 2, 'support_staff', 'REQ-000107', 'agent_update', '2026-01-06T09:02:00', 'Thanks for your message. We are reviewing your request and will update you by the next business day.'),
('MSG-TKT-2026-000001-003', 'TKT-2026-000001', 3, 'support_staff', 'REQ-000107', 'answer', '2026-01-06T10:50:00', 'Good news, I found the relevant policy. Financial aid is disbursed 10 days after the term census date. Source: Aid status and disbursement: Standard Procedure, version 1 (effective 2025-08-14).'),
('MSG-TKT-2026-000002-001', 'TKT-2026-000002', 1, 'requester', 'REQ-000088', 'question', '2026-01-07T11:06:00', 'Something about transcripts and records does not look right on my record, what should I do?'),
('MSG-TKT-2026-000002-002', 'TKT-2026-000002', 2, 'support_staff', 'REQ-000108', 'clarification_request', '2026-01-08T15:30:00', 'Could you clarify your question? Is it related to transcripts and records, grade change and roster correction, add, drop and withdraw?'),
('MSG-TKT-2026-000002-003', 'TKT-2026-000002', 3, 'requester', 'REQ-000088', 'clarification_reply', '2026-01-09T03:24:00', 'Sorry for the confusion, my question is about transcripts and records. How much does an official transcript cost?'),
('MSG-TKT-2026-000002-004', 'TKT-2026-000002', 4, 'support_staff', 'REQ-000108', 'answer', '2026-01-13T11:05:00', 'Good news, I found the relevant policy. Each official transcript costs 5 USD. Official transcripts are processed within 3 business days. Source: Transcripts and records: Standard Procedure, version 1 (effective 2025-10-02).'),
('MSG-TKT-2026-000003-001', 'TKT-2026-000003', 1, 'requester', 'REQ-000071', 'question', '2026-01-07T15:42:00', 'I need to know: How recent does my supporting documentation need to be? My deadline is Jan 07 at 19:39, so this is time sensitive.'),
('MSG-TKT-2026-000003-002', 'TKT-2026-000003', 2, 'support_staff', 'REQ-000116', 'answer', '2026-01-07T15:54:00', 'Hi, Supporting documentation must be dated within 3 years. Intake requests are acknowledged within 3 business days. Source: Accommodation intake information: Standard Procedure, version 3 (effective 2025-11-24).'),
('MSG-TKT-2026-000004-001', 'TKT-2026-000004', 1, 'requester', 'REQ-000040', 'question', '2026-01-08T11:43:00', 'Hello, quick question: How long does review of my submitted documents take? This is urgent because of a deadline on Jan 10 at 21:25.'),
