('MSG-TKT-2026-000038-002', 'TKT-2026-000038', 2, 'support_staff', 'REQ-000111', 'clarification_request', '2026-02-11T08:13:00', 'Could you clarify your question? Is it related to wi-fi and software licenses, security incident, account, password and mfa?'),
('MSG-TKT-2026-000038-003', 'TKT-2026-000038', 3, 'requester', 'REQ-000040', 'requester_followup', '2026-02-11T12:27:00', 'Could someone look at this today? Thanks.'),
