('MSG-TKT-2026-000127-005', 'TKT-2026-000127', 5, 'requester', 'REQ-000029', 'requester_followup', '2026-06-08T22:58:00', 'Just checking in, I have not heard back yet.'),
('MSG-TKT-2026-000127-006', 'TKT-2026-000127', 6, 'requester', 'REQ-000029', 'clarification_reply', '2026-06-09T13:36:00', 'It is about account, password and mfa. Specifically: How often do I have to change my password?'),
('MSG-TKT-2026-000127-007', 'TKT-2026-000127', 7, 'support_staff', 'REQ-000112', 'answer', '2026-06-10T10:52:00', 'Hi, Passwords expire every 180 days. Source: Account, password and MFA: Standard Procedure, version 1 (effective 2025-05-24).'),
('MSG-TKT-2026-000128-001', 'TKT-2026-000128', 1, 'requester', 'REQ-000040', 'question', '2026-06-08T17:41:00', 'Hi, How long do I have to submit my verification documents?'),
('MSG-TKT-2026-000128-002', 'TKT-2026-000128', 2, 'requester', 'REQ-000040', 'requester_followup', '2026-06-09T00:57:00', 'Any update on this?'),
('MSG-TKT-2026-000128-003', 'TKT-2026-000128', 3, 'support_staff', 'REQ-000107', 'agent_update', '2026-06-09T10:10:00', 'Quick update: your request is in progress, no action needed from you yet.'),
('MSG-TKT-2026-000128-004', 'TKT-2026-000128', 4, 'support_staff', 'REQ-000107', 'answer', '2026-06-11T16:47:00', 'Thanks for your patience. Verification documents are due within 21 days of the request notice. Submitted documents are reviewed within 15 business days. Source: Verification documents: Standard Procedure, version 2 (effective 2025-07-05).'),
('MSG-TKT-2026-000129-001', 'TKT-2026-000129', 1, 'requester', 'REQ-000040', 'question', '2026-06-10T13:37:00', 'Could you tell me? How long do student software licenses last?'),
('MSG-TKT-2026-000129-002', 'TKT-2026-000129', 2, 'requester', 'REQ-000040', 'requester_followup', '2026-06-10T23:27:00', 'Following up on my request.'),
('MSG-TKT-2026-000129-003', 'TKT-2026-000129', 3, 'support_staff', 'REQ-000113', 'agent_update', '2026-06-11T10:01:00', 'Quick update: your request is in progress, no action needed from you yet.'),
('MSG-TKT-2026-000129-004', 'TKT-2026-000129', 4, 'support_staff', 'REQ-000113', 'answer', '2026-06-13T13:05:00', 'Good news, I found the relevant policy. Licensed software is activated for 180 days per grant. Each user may register up to 3 devices. Source: Wi-Fi and software licenses: Standard Procedure, version 2 (effective 2026-05-20).');
INSERT INTO "message" ("message_id", "ticket_id", "message_seq", "sender_type", "sender_id", "message_type", "sent_at", "body") VALUES
('MSG-TKT-2026-000130-001', 'TKT-2026-000130', 1, 'requester', 'REQ-000063', 'question', '2026-06-11T20:22:00', 'How long do official transcripts take to process? Thanks in advance.'),
('MSG-TKT-2026-000130-002', 'TKT-2026-000130', 2, 'support_staff', 'REQ-000109', 'agent_update', '2026-06-12T15:48:00', 'Quick update: your request is in progress, no action needed from you yet.'),
('MSG-TKT-2026-000130-003', 'TKT-2026-000130', 3, 'support_staff', 'REQ-000109', 'answer', '2026-06-15T11:27:00', 'Hi, Official transcripts are processed within 2 business days. Each official transcript costs 10 USD. Source: Transcripts and records: Standard Procedure, version 2 (effective 2026-06-13).'),
('MSG-TKT-2026-000130-004', 'TKT-2026-000130', 4, 'requester', 'REQ-000063', 'thanks', '2026-06-19T07:02:00', 'Got it, thanks.'),
('MSG-TKT-2026-000131-001', 'TKT-2026-000131', 1, 'requester', 'REQ-000101', 'question', '2026-06-12T12:14:00', 'Could you tell me? How long do student software licenses last?'),
('MSG-TKT-2026-000131-002', 'TKT-2026-000131', 2, 'support_staff', 'REQ-000111', 'agent_update', '2026-06-12T16:54:00', 'We have picked up your case and are checking the details now.'),
('MSG-TKT-2026-000131-003', 'TKT-2026-000131', 3, 'support_staff', 'REQ-000111', 'answer', '2026-06-16T10:51:00', 'Thanks for your patience. Licensed software is activated for 180 days per grant. Source: Wi-Fi and software licenses: Standard Procedure, version 2 (effective 2026-05-20).'),
('MSG-TKT-2026-000132-001', 'TKT-2026-000132', 1, 'requester', 'REQ-000091', 'question', '2026-06-13T12:41:00', 'Could you tell me? How far ahead must I book an accommodated exam?'),
('MSG-TKT-2026-000132-002', 'TKT-2026-000132', 2, 'support_staff', 'REQ-000114', 'answer', '2026-06-15T09:53:00', 'Hi, Accommodated exams must be booked 3 days before the exam date. Source: Exam accommodation logistics: Standard Procedure, version 3 (effective 2026-05-29).'),
('MSG-TKT-2026-000132-003', 'TKT-2026-000132', 3, 'requester', 'REQ-000091', 'reopen_request', '2026-06-16T07:28:00', 'This did not fully answer my question, can you recheck?'),
('MSG-TKT-2026-000132-004', 'TKT-2026-000132', 4, 'support_staff', 'REQ-000114', 'answer', '2026-06-16T09:16:00', 'Hi, Accommodated exams must be booked 3 days before the exam date. Standard extended time is 50 percent of the regular exam length. Source: Exam accommodation logistics: Standard Procedure, version 3 (effective 2026-05-29).'),
('MSG-TKT-2026-000133-001', 'TKT-2026-000133', 1, 'requester', 'REQ-000056', 'question', '2026-06-15T09:58:00', 'When will my financial aid be disbursed to my account? Thanks in advance.'),
('MSG-TKT-2026-000133-002', 'TKT-2026-000133', 2, 'system', NULL, 'system_ack', '2026-06-15T10:00:00', 'Your request TKT-2026-000133 was received and routed to the Financial Aid Office. Keep this reference for follow-ups.'),
('MSG-TKT-2026-000133-003', 'TKT-2026-000133', 3, 'requester', 'REQ-000056', 'requester_followup', '2026-06-15T12:36:00', 'Could someone look at this today? Thanks.'),
('MSG-TKT-2026-000133-004', 'TKT-2026-000133', 4, 'support_staff', 'REQ-000105', 'agent_update', '2026-06-15T14:21:00', 'We have picked up your case and are checking the details now.'),
('MSG-TKT-2026-000133-005', 'TKT-2026-000133', 5, 'support_staff', 'REQ-000105', 'answer', '2026-06-18T12:41:00', 'Hi, Financial aid is disbursed 10 days after the term census date. Source: Aid status and disbursement: Standard Procedure, version 2 (effective 2026-05-13).'),
('MSG-TKT-2026-000134-001', 'TKT-2026-000134', 1, 'requester', 'REQ-000091', 'question', '2026-06-15T19:51:00', 'How often do I have to change my password? Thanks in advance.'),
('MSG-TKT-2026-000134-002', 'TKT-2026-000134', 2, 'requester', 'REQ-000091', 'requester_followup', '2026-06-16T05:27:00', 'Could someone look at this today? Thanks.'),
('MSG-TKT-2026-000134-003', 'TKT-2026-000134', 3, 'support_staff', 'REQ-000113', 'answer', '2026-06-16T08:34:00', 'Good news, I found the relevant policy. Passwords expire every 180 days. Accounts lock for 30 minutes after five failed sign-ins. Source: Account, password and MFA: Standard Procedure, version 1 (effective 2025-05-24).'),
('MSG-TKT-2026-000134-004', 'TKT-2026-000134', 4, 'requester', 'REQ-000091', 'thanks', '2026-06-19T12:27:00', 'Thanks, that resolves it.'),
('MSG-TKT-2026-000135-001', 'TKT-2026-000135', 1, 'requester', 'REQ-000033', 'question', '2026-06-17T14:27:00', 'Hi, How long do I have to submit my verification documents?'),
('MSG-TKT-2026-000135-002', 'TKT-2026-000135', 2, 'support_staff', 'REQ-000105', 'answer', '2026-06-18T10:00:00', 'Good news, I found the relevant policy. Verification documents are due within 21 days of the request notice. Submitted documents are reviewed within 15 business days. Source: Verification documents: Standard Procedure, version 2 (effective 2025-07-05).'),
('MSG-TKT-2026-000136-001', 'TKT-2026-000136', 1, 'requester', 'REQ-000001', 'question', '2026-06-18T14:58:00', 'Hello, quick question: When is my tuition payment due?'),
('MSG-TKT-2026-000136-002', 'TKT-2026-000136', 2, 'support_staff', 'REQ-000105', 'answer', '2026-06-18T16:44:00', 'Hello, Tuition is due 7 days before the term start date. Source: Tuition payment and refunds: Standard Procedure, version 2 (effective 2025-05-20).'),
('MSG-TKT-2026-000137-001', 'TKT-2026-000137', 1, 'requester', 'REQ-000040', 'question', '2026-06-18T16:55:00', 'Could you tell me? When will my course show up in the learning platform? I need this sorted before Jun 21 at 08:58.'),
('MSG-TKT-2026-000137-002', 'TKT-2026-000137', 2, 'requester', 'REQ-000040', 'requester_followup', '2026-06-18T17:52:00', 'Any update on this?'),
('MSG-TKT-2026-000137-003', 'TKT-2026-000137', 3, 'requester', 'REQ-000040', 'requester_followup', '2026-06-18T18:24:00', 'Any update on this?'),
('MSG-TKT-2026-000137-004', 'TKT-2026-000137', 4, 'support_staff', 'REQ-000111', 'answer', '2026-06-18T18:43:00', 'Hi, Courses appear in the learning platform within 4 hours of enrollment. Source: LMS and course access: Standard Procedure, version 2 (effective 2025-04-17).'),
('MSG-TKT-2026-000138-001', 'TKT-2026-000138', 1, 'requester', 'REQ-000024', 'question', '2026-06-21T13:48:00', 'Hello, quick question: What is the last day to add a course?'),
('MSG-TKT-2026-000138-002', 'TKT-2026-000138', 2, 'support_staff', 'REQ-000108', 'answer', '2026-06-22T13:45:00', 'Hi, Courses may be added through day 5 of the term. Withdrawal with a W grade is allowed through day 60 of the term. Source: Add, drop and withdraw: Standard Procedure, version 3 (effective 2025-08-27).'),
('MSG-TKT-2026-000139-001', 'TKT-2026-000139', 1, 'requester', 'REQ-000095', 'question', '2026-06-23T11:10:00', 'Hi team, How long will my account be frozen during review? I could not find it on the website.'),
('MSG-TKT-2026-000139-002', 'TKT-2026-000139', 2, 'support_staff', 'REQ-000113', 'answer', '2026-06-23T12:49:00', 'Thanks for your patience. Compromised accounts are frozen for up to 72 hours during review. Suspected compromises must be reported within 4 hours. Source: Security incident: Standard Procedure, version 2 (effective 2026-04-06).'),
('MSG-TKT-2026-000139-003', 'TKT-2026-000139', 3, 'support_staff', 'REQ-000113', 'escalation_note', '2026-06-23T13:12:00', 'I am escalating this to the Platform Administration because this request type needs a documented human decision.'),
('MSG-TKT-2026-000139-004', 'TKT-2026-000139', 4, 'support_staff', 'REQ-000124', 'handoff_response', '2026-07-02T13:22:00', 'After specialist review: we have approved the request and updated your record. Compromised accounts are frozen for up to 72 hours during review. Source: Security incident: Standard Procedure, version 2 (effective 2026-04-06).'),
('MSG-TKT-2026-000139-005', 'TKT-2026-000139', 5, 'requester', 'REQ-000095', 'thanks', '2026-07-06T03:16:00', 'Perfect, thank you for the quick help.'),
('MSG-TKT-2026-000140-001', 'TKT-2026-000140', 1, 'requester', 'REQ-000027', 'question', '2026-06-24T10:38:00', 'Hi, How long is my account locked after failed sign-ins?'),
('MSG-TKT-2026-000140-002', 'TKT-2026-000140', 2, 'support_staff', 'REQ-000113', 'answer', '2026-06-24T12:37:00', 'Hi, Accounts lock for 30 minutes after five failed sign-ins. Passwords expire every 180 days. Source: Account, password and MFA: Standard Procedure, version 1 (effective 2025-05-24).'),
('MSG-TKT-2026-000141-001', 'TKT-2026-000141', 1, 'requester', 'REQ-000033', 'question', '2026-06-25T15:08:00', 'Hi, How long does it take to clear a registration hold?'),
('MSG-TKT-2026-000141-002', 'TKT-2026-000141', 2, 'support_staff', 'REQ-000109', 'agent_update', '2026-06-25T16:47:00', 'We have picked up your case and are checking the details now.'),
('MSG-TKT-2026-000141-003', 'TKT-2026-000141', 3, 'support_staff', 'REQ-000109', 'answer', '2026-07-01T12:17:00', 'Hello, Registration holds are cleared within 2 business days of resolution. Prerequisite overrides must be approved by the course instructor. Source: Holds and prerequisites: Standard Procedure, version 1 (effective 2025-07-14).'),
('MSG-TKT-2026-000142-001', 'TKT-2026-000142', 1, 'requester', 'REQ-000091', 'question', '2026-06-29T10:43:00', 'Need help with the thing we discussed last term.'),
