('MSG-TKT-2026-000151-001', 'TKT-2026-000151', 1, 'requester', 'REQ-000030', 'question', '2026-07-09T18:55:00', 'Could you tell me? When will my financial aid be disbursed to my account?'),
('MSG-TKT-2026-000151-002', 'TKT-2026-000151', 2, 'support_staff', 'REQ-000105', 'agent_update', '2026-07-10T11:41:00', 'Thanks for your message. We are reviewing your request and will update you by the next business day.'),
('MSG-TKT-2026-000151-003', 'TKT-2026-000151', 3, 'support_staff', 'REQ-000105', 'answer', '2026-07-13T13:08:00', 'Hello, Financial aid is disbursed 10 days after the term census date. Aid requires enrollment in at least 12 credit hours. Source: Aid status and disbursement: Standard Procedure, version 2 (effective 2026-05-13).'),
('MSG-TKT-2026-000152-001', 'TKT-2026-000152', 1, 'requester', 'REQ-000050', 'question', '2026-07-10T12:16:00', 'Could you tell me? What is the last day to add a course?'),
