('MSG-TKT-2026-000243-005', 'TKT-2026-000243', 5, 'support_staff', 'REQ-000113', 'answer', '2026-10-19T11:43:00', 'Hi, Licensed software is activated for 180 days per grant. Source: Wi-Fi and software licenses: Standard Procedure, version 2 (effective 2026-05-20).'),
('MSG-TKT-2026-000244-001', 'TKT-2026-000244', 1, 'requester', 'REQ-000042', 'question', '2026-10-15T16:22:00', 'I have a question about account, password and mfa but I am not sure what applies to my situation.'),
('MSG-TKT-2026-000244-002', 'TKT-2026-000244', 2, 'system', NULL, 'system_ack', '2026-10-15T16:25:00', 'Your request TKT-2026-000244 was received and routed to the IT Help Desk. Keep this reference for follow-ups.'),
('MSG-TKT-2026-000244-003', 'TKT-2026-000244', 3, 'support_staff', 'REQ-000113', 'clarification_request', '2026-10-16T09:38:00', 'Thanks for reaching out. So I can point you to the right policy, which topic is this about: lms and course access, security incident, account, password and mfa?'),
('MSG-TKT-2026-000244-004', 'TKT-2026-000244', 4, 'requester', 'REQ-000042', 'clarification_reply', '2026-10-16T16:50:00', 'It is about account, password and mfa. Specifically: How often do I have to change my password?'),
('MSG-TKT-2026-000244-005', 'TKT-2026-000244', 5, 'support_staff', 'REQ-000113', 'answer', '2026-10-20T09:11:00', 'Thanks for your patience. Passwords expire every 365 days. Accounts lock for 30 minutes after five failed sign-ins. Source: Account, password and MFA: Standard Procedure, version 2 (effective 2026-08-08).'),
('MSG-TKT-2026-000245-001', 'TKT-2026-000245', 1, 'requester', 'REQ-000085', 'question', '2026-10-15T19:41:00', 'I have a problem, I do not know who to ask. My deadline is Oct 22 at 20:46, so this is time sensitive.'),
('MSG-TKT-2026-000245-002', 'TKT-2026-000245', 2, 'support_staff', 'REQ-000115', 'clarification_request', '2026-10-16T11:30:00', 'Thanks for reaching out. So I can point you to the right policy, which topic is this about: assistive technology, exam accommodation logistics, accommodation determination?'),
('MSG-TKT-2026-000245-003', 'TKT-2026-000245', 3, 'requester', 'REQ-000085', 'clarification_reply', '2026-10-16T15:47:00', 'I am not sure, it is complicated and I cannot explain it better.'),
('MSG-TKT-2026-000245-004', 'TKT-2026-000245', 4, 'support_staff', 'REQ-000115', 'clarification_request', '2026-10-19T09:16:00', 'Thanks for reaching out. So I can point you to the right policy, which topic is this about: assistive technology, accommodation determination, exam accommodation logistics?'),
('MSG-TKT-2026-000245-005', 'TKT-2026-000245', 5, 'requester', 'REQ-000085', 'requester_followup', '2026-10-21T08:18:00', 'Following up on my request.'),
('MSG-TKT-2026-000245-006', 'TKT-2026-000245', 6, 'support_staff', 'REQ-000115', 'escalation_note', '2026-10-21T09:16:00', 'Escalating to the Academic Administration Office because the question is still unclear after two clarification attempts.'),
('MSG-TKT-2026-000245-007', 'TKT-2026-000245', 7, 'support_staff', 'REQ-000118', 'handoff_response', '2026-10-26T15:20:00', 'After specialist review: we have granted a one-time exception and recorded it on your file.'),
('MSG-TKT-2026-000246-001', 'TKT-2026-000246', 1, 'requester', 'REQ-000003', 'question', '2026-10-16T17:19:00', 'Hi, How long does review of my submitted documents take?'),
('MSG-TKT-2026-000246-002', 'TKT-2026-000246', 2, 'support_staff', 'REQ-000105', 'answer', '2026-10-21T09:30:00', 'Good news, I found the relevant policy. Submitted documents are reviewed within 5 business days. Verification documents are due within 45 days of the request notice. Source: Verification documents: Standard Procedure, version 3 (effective 2026-08-13).'),
('MSG-TKT-2026-000247-001', 'TKT-2026-000247', 1, 'requester', 'REQ-000085', 'question', '2026-10-19T16:23:00', 'How long after the term can a grade change be filed? Thanks in advance.'),
('MSG-TKT-2026-000247-002', 'TKT-2026-000247', 2, 'support_staff', 'REQ-000110', 'answer', '2026-10-20T10:21:00', 'Good news, I found the relevant policy. Grade changes must be filed within 90 days after the term ends. Grade changes require approval from the registrar. Source: Grade change and roster correction: Standard Procedure, version 4 (effective 2025-12-18).'),
('MSG-TKT-2026-000247-003', 'TKT-2026-000247', 3, 'support_staff', 'REQ-000110', 'escalation_note', '2026-10-20T11:04:00', 'I am escalating this to the Academic Administration Office because this request type needs a documented human decision.'),
('MSG-TKT-2026-000247-004', 'TKT-2026-000247', 4, 'support_staff', 'REQ-000119', 'handoff_response', '2026-10-20T14:36:00', 'Decision from the Academic Administration Office: we cannot approve this request as submitted; the policy terms apply. Grade changes must be filed within 90 days after the term ends. Source: Grade change and roster correction: Standard Procedure, version 4 (effective 2025-12-18).'),
('MSG-TKT-2026-000248-001', 'TKT-2026-000248', 1, 'requester', 'REQ-000023', 'question', '2026-10-20T16:02:00', 'How long can I borrow assistive technology? Thanks in advance.'),
('MSG-TKT-2026-000248-002', 'TKT-2026-000248', 2, 'support_staff', 'REQ-000115', 'answer', '2026-10-20T16:37:00', 'Thanks for your patience. Assistive technology may be loaned for 90 days per term. Source: Assistive technology: Standard Procedure, version 4 (effective 2026-05-30).'),
('MSG-TKT-2026-000249-001', 'TKT-2026-000249', 1, 'requester', 'REQ-000051', 'question', '2026-10-20T16:42:00', 'Hi, How often do I have to change my password? This is urgent because of a deadline on Oct 23 at 09:03.'),
('MSG-TKT-2026-000249-002', 'TKT-2026-000249', 2, 'support_staff', 'REQ-000111', 'answer', '2026-10-20T17:43:00', 'Good news, I found the relevant policy. Passwords expire every 365 days. Accounts lock for 30 minutes after five failed sign-ins. Source: Account, password and MFA: Standard Procedure, version 2 (effective 2026-08-08).'),
('MSG-TKT-2026-000250-001', 'TKT-2026-000250', 1, 'requester', 'REQ-000048', 'question', '2026-10-22T10:17:00', 'Hi team, How long is my account locked after failed sign-ins? I could not find it on the website.'),
('MSG-TKT-2026-000250-002', 'TKT-2026-000250', 2, 'support_staff', 'REQ-000112', 'agent_update', '2026-10-22T11:34:00', 'We have picked up your case and are checking the details now.'),
('MSG-TKT-2026-000250-003', 'TKT-2026-000250', 3, 'requester', 'REQ-000048', 'requester_followup', '2026-10-22T15:02:00', 'Following up on my request.'),
('MSG-TKT-2026-000250-004', 'TKT-2026-000250', 4, 'support_staff', 'REQ-000112', 'answer', '2026-10-22T17:44:00', 'Good news, I found the relevant policy. Accounts lock for 30 minutes after five failed sign-ins. Passwords expire every 365 days. Source: Account, password and MFA: Standard Procedure, version 2 (effective 2026-08-08).'),
('MSG-TKT-2026-000250-005', 'TKT-2026-000250', 5, 'requester', 'REQ-000048', 'thanks', '2026-10-26T18:52:00', 'Thanks, that resolves it.');
